</form>
<script>(()=>{const p=document.getElementById('product_id'),s=document.getElementById('system_quantity'),c=document.getElementById('physical_count'),d=document.getElementById('difference-preview');let currentStock=null;async function update(){if(!p.value){currentStock=null;s.value='Select a product';d.textContent='Select a product to calculate the difference.';return;}s.value='Loading…';try{const r=await fetch('/api/products/'+encodeURIComponent(p.value)+'/stock',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error();const json=await r.json();currentStock=Number(json.data.quantity);s.value=currentStock;const diff=Number(c.value||0)-currentStock;d.textContent='Adjustment difference: '+(diff>0?'+':'')+diff+' unit(s)';}catch(e){currentStock=null;s.value='Could not load stock';d.textContent='Stock could not be loaded. Refresh the page and try again.';}}p.addEventListener('change',update);c.addEventListener('input',()=>{if(currentStock!==null){const diff=Number(c.value||0)-currentStock;d.textContent='Adjustment difference: '+(diff>0?'+':'')+diff+' unit(s)';}});update();})();</script>
